import { demoRecords, demoPlan, starterStory, suggestedQuestions } from './fixtures.js';
import { dailyFrequency, durationDays, conditionalSchedule, validateReminders } from './calendar.js';
import { addPlanVersion, findDocument, markPatientCorrection, planVersions, recordQuestionReply, questionDocuments } from './journey.js';
import { newVisit, saveNoteVersion, nextVisit, previousVisitContext, hasVisitContent, noteHasChanges } from './visits.js';
import { createLocalStore, STORAGE_KEY } from './storage.js';

const $=(s,root=document)=>root.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const paths={
 camera:'M3 7h5l2-3h4l2 3h5v14H3zM16 14a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 note:'M7 3h8l4 4v14H7zM15 3v5h4M10 12h6M10 16h6',
 chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-1 2V11.5a8.5 8.5 0 0 1 17 0zM7 10h9M7 14h5',
 arrow:'M5 12h14M13 6l6 6-6 6', send:'m12 4 7 15-7-4-7 4 7-15zM12 15V4',
 check:'m5 12 4 4L19 6', chevron:'m9 5 7 7-7 7', plus:'M12 5v14M5 12h14',
 source:'M9 15 15 9M8 7l2-2a4 4 0 0 1 6 6l-2 2M16 17l-2 2a4 4 0 0 1-6-6l2-2',
 clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',
 upload:'M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5',
 pill:'m8 16 8-8M7 19a5 5 0 0 1-7-7l8-8a5 5 0 0 1 7 7l-8 8z',
 calendar:'M5 5h14v16H5zM8 2v6M16 2v6M5 10h14M9 14h2M14 14h2M9 17h2',
 test:'M9 3h6M10 3v7L5 19q-1 2 2 2h10q3 0 2-2l-5-9V3M8 15h8',
 doctor:'M9 3H5v7a5 5 0 0 0 10 0V3h-4M10 15v2a4 4 0 0 0 8 0v-3M20 11a2 2 0 1 1-4 0 2 2 0 0 1 4 0',
 user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-2a8 8 0 0 1 16 0v2',
 spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3z',
 info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 close:'m6 6 12 12M6 18 18 6', reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',
 copy:'M9 8h12v13H9zM15 8V3H3v13h6', down:'M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3',
 globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',
 edit:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6z', shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zM8 12l3 3 5-6',
 folder:'M3 6h7l2 3h9v12H3z', pause:'M8 5v14M16 5v14', question:'M9 8a3 3 0 1 1 5 3c-2 1-2 2-2 3M12 18h.01',
 history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2'
};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;}

const fresh=()=>({visit:newVisit(),noteVersions:[],visitHistory:[],carryover:null,ocrPhotoMissing:false,lang:'zh',view:'prepare',busy:'',error:null,health:null,demo:false,
 intake:{messages:[],records:[],facts:[],unknowns:[],turn:0,aid:'open_question',question:'',options:[],ready:false,reviewed:false},
 documents:[],plan:null,versions:[],preference:'brief',checks:{},checkOpen:null,completed:{},questions:[],
 reminders:[],calendar:null,photoPreviews:[],ocrPending:false,ocrReviewed:false,recordDraft:null,postMessages:[],activities:[],draftIntake:'',draftPost:'',draftPlanText:'',draftCheck:'',lastMeta:null});
// Accessing the localStorage property itself can throw in restricted browsers.
const localStore=createLocalStore({getItem:key=>window.localStorage.getItem(key),setItem:(key,value)=>window.localStorage.setItem(key,value),removeItem:key=>window.localStorage.removeItem(key)});
const recovered=localStore.load(fresh());
let state=recovered.state,storageError=recovered.error;
let retryAction=null, uploadContext='plan', toastTimer;
const tr=(zh,en)=>state.lang==='en'?en:zh;
const time=(date=new Date())=>date.toLocaleTimeString(state.lang==='en'?'en-US':'zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
const busyAttr=()=>state.busy?'disabled aria-busy="true"':'';
const kindName=k=>({medication:tr('用药','Medication'),test:tr('检查','Test'),followup:tr('复诊','Follow-up'),instruction:tr('注意事项','Instruction')}[k]||tr('安排','Plan item'));
const missingName=f=>({dose:tr('每次用量','Dose'),frequency:tr('用药频率','Frequency'),duration:tr('疗程','Duration'),timing:tr('执行时间','Timing'),preparation:tr('检查前准备','Test preparation'),date:tr('日期','Date')}[f]||f);
const checkName=s=>({matched:tr('理解已核对','Understanding checked'),mismatch:tr('仍需澄清','Needs clarification'),uncertain:tr('理解尚未确认','Understanding not confirmed'),skipped:tr('已跳过核对','Check skipped')}[s]||tr('未核对','Not checked'));
const routeName=r=>({explanation:tr('来自本次资料','From your records'),source_missing:tr('资料未写明','Not in the records'),clinical_review:tr('需要专业判断','Needs professional input')}[r]||'');
const routeClass=r=>r==='clinical_review'?'rose':r==='source_missing'?'amber':'teal';
const priorityItem=()=>state.plan?.complexity?.level!=='low'?state.plan?.items.find(i=>i.kind==='medication'&&i.dose&&i.frequency&&i.duration)?.id:null;
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400);}
function activity(zh,en,detail=''){state.activities.unshift({zh,en,detail,time:time()});}

function render(save=true){
 if(save)persistLocal();
 document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';
 document.title=tr('AfterDoc · 把每次就诊，接下去','AfterDoc · Carry the conversation forward');
 const names={prepare:tr('就诊前','Before your visit'),doctor:tr('我的医嘱','My visit records'),after:tr('就诊后','After your visit'),note:tr('我的小纸条','Your living note')};
 $('#app').innerHTML=`<div class="layout">${sidebar()}<div class="workspace"><header class="topbar"><div class="breadcrumb">${icon('folder',14)}<span>${visitLabel(state.visit.number)}</span><span>/</span><strong>${names[state.view]}</strong></div><div class="topbar-right"><span class="connection"><span class="dot ${state.health?.configured?'online':''}"></span>${state.lastMeta?'DeepSeek · '+tr('已连接','connected'):state.health?.configured?'DeepSeek · '+tr('已配置','configured'):tr('正在检查连接','Checking connection')}</span><button class="icon-button" data-action="language" aria-label="${tr('切换至英文','Switch to Chinese')}" title="中文 / English">${icon('globe',16)}</button><span class="avatar">L</span></div></header><main id="main" class="content">${errorBanner()}<div id="storage-feedback">${storageBanner()}</div>${state.view==='prepare'?prepareView():state.view==='doctor'?doctorView():state.view==='after'?afterView():noteView()}<footer class="footer-note"><span>${tr('资料保存在此浏览器 · 可在“关于”中清除','Records stay in this browser · Clear them in About')}</span><span>AFTERDOC / 2026</span></footer></main></div></div>`;
 if(state.busy)document.body.setAttribute('aria-busy','true');else document.body.removeAttribute('aria-busy');
 for(const el of document.querySelectorAll('.conversation'))el.scrollTop=el.scrollHeight;
}
function sidebar(){
 const stages=[['prepare','01',tr('把话说清楚','Tell your story'),tr('PRE-VISIT · 诊前','PRE-VISIT')],['doctor','02',tr('拍下这次医嘱','Capture your plan'),tr('我的资料 · 上传','YOUR RECORDS')],['after','03',tr('看懂并执行','Understand & act'),tr('POST-VISIT · 诊后','POST-VISIT')],['note','04',tr('带着问题回来','Carry it forward'),tr('LIVING NOTE · 小纸条','LIVING NOTE')]];
 return `<aside class="sidebar"><div><a class="brand" href="#" data-action="view" data-view="prepare" aria-label="AfterDoc home"><span class="brand-mark">${icon('note',27)}</span><span class="brand-name">AfterDoc</span></a><div class="brand-caption">CARE, CONTINUED.</div></div><div><div class="sidebar-label">${tr('一次就诊的前后','YOUR VISIT, CONNECTED')}</div><nav class="stage-nav" aria-label="${tr('就诊阶段','Visit stages')}">${stages.map(([key,num,name,sub])=>`<button class="stage ${state.view===key?'active':''}" data-action="view" data-view="${key}" ${state.view===key?'aria-current="step"':''}><span class="stage-number">${num}</span><span><span class="stage-name">${name}</span><span class="mobile-stage-name">${{prepare:tr('诊前描述','Your story'),doctor:tr('我的医嘱','Records'),after:tr('诊后安排','Care plan'),note:tr('就诊小条','Visit note')}[key]}</span><span class="stage-sub">${sub}</span></span></button>`).join('')}</nav></div><div class="sidebar-note"><strong>${tr('你的节奏，你的理解。','At your pace.')}</strong>${tr('想简短一点，或多问一句，都可以。','A little guidance, or a little more explanation. You choose.')}</div><div class="sidebar-bottom"><button data-action="demo">${icon('spark',15)}${tr('体验虚构诊后病例','Try the fictional case')}</button><button data-action="reset">${icon('reset',15)}${tr('准备下一次就诊','Prepare next visit')}</button><button data-action="about">${icon('info',15)}${tr('关于这个原型','About this prototype')}</button><div class="deadline-note">${tr('专业判断始终留给医生。','Clinical decisions stay with your clinician.')}</div></div></aside>`;
}
function errorBanner(){if(!state.error)return '';return `<div class="banner" role="alert">${icon('info',18)}<div class="text"><strong>${tr('这一步还没有完成','This step did not finish')}</strong>${esc(state.error)}</div>${retryAction?`<button class="button small secondary" data-action="retry">${tr('重试','Retry')}</button>`:''}<button class="icon-button" data-action="dismiss-error" aria-label="${tr('关闭错误提示','Dismiss error')}">${icon('close',15)}</button></div>`;}
function heading(eyebrow,title,lead,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p></div>${action}</div>`;}
function prepareView(){
 return `${heading('BEFORE YOUR VISIT',tr('把想说的，慢慢说清楚。','Your story, in your own words.'),tr('不用先知道医学术语。从最困扰你的事情说起，我们一起整理。','Start with what is bothering you. We will help you make it clear.'),`<button class="button secondary heading-action" data-action="demo">${icon('spark',15)}${tr('直接体验诊后流程','Try the post-visit demo')}</button>`)} ${carryoverPanel()}${recordRecoveryPanel()}<div class="main-grid"><div><section class="panel"><div class="panel-head"><div class="panel-head-title"><span class="icon-box">${icon('chat')}</span><div><h2>${tr('先聊聊你的情况','Let’s start with your experience')}</h2><p>${tr('一次只聊清楚一件事','One detail at a time')}</p></div></div><span class="chip teal">${tr('你来决定节奏','At your pace')}</span></div><div class="conversation" role="log" aria-live="polite">${intakeMessages()}</div>${state.busy==='intake'?loading(tr('正在整理原话，选择下一步澄清方式…','Organizing your words and choosing what to clarify…')):aidView()}${composer('intake')}</section>${state.intake.facts.length?patientReview():''}</div><aside class="right-stack">${livingNotePreview('pre')}${state.questions.length?pendingPreview():''}<div class="help-card"><h3>${tr('记不清，也是一种有效回答','“I’m not sure” is a useful answer')}</h3><p>${tr('我们会保留不确定的地方。你可以跳过、暂停，也可以随时更正之前的话。','We keep uncertainty visible. You can skip, pause, or correct something you said.')}</p></div>${activityView()}</aside></div>`;
}
function intakeMessages(){
 const intro=tr('你好，我会帮你把经历整理成一份给医生看的小纸条。\n\n这次就诊，你最想让医生知道什么？','Hi. I can help organize your experience into a short note for your clinician.\n\nWhat would you most like them to know about this visit?');
 return messageView({role:'assistant',content:intro})+state.intake.messages.map(messageView).join('');
}
function messageView(m){
 return `<div class="message ${m.role==='user'?'user':''}"><div class="speaker">${icon(m.role==='user'?'user':'note',15)}</div><div class="message-body"><div class="message-label">${m.role==='user'?tr('你','You'):'AfterDoc'}</div>${m.route?`<div class="route-label"><span class="chip ${routeClass(m.route)}">${routeName(m.route)}</span></div>`:''}<div class="bubble">${esc(m.content)}</div>${m.citations?.length?`<div class="message-citations">${m.citations.map(c=>sourceButton(c.sourceId,c.quote)).join('')}</div>`:''}</div></div>`;
}
function sourceButton(id,quote,label=''){return `<button class="source-link" data-action="source" data-source="${esc(id)}" data-quote="${esc(quote)}">${icon('source',12)}${label||tr('查看原文','View source')}</button>`;}
function loading(label){return `<div class="busy-indicator" role="status"><span class="spinner"></span>${label}</div>`;}
function composer(which){
 const pre=which==='intake';const value=pre?state.draftIntake:state.draftPost;
 return `<form class="composer" data-form="${which}">${pre&&!state.intake.messages.length?`<div class="suggestions"><button type="button" class="suggestion" data-action="starter">${tr('试试：「吃完饭总是不太舒服」','Try: “I feel uncomfortable after meals”')}</button></div>`:!pre?`<div class="suggestions">${suggestedQuestions[state.lang].slice(0,3).map(q=>`<button type="button" class="suggestion" data-action="ask-suggestion" data-question="${esc(q)}" ${busyAttr()}>${esc(q)}</button>`).join('')}</div>`:''}<div class="compose-box"><label class="sr-only" for="${which}-input">${pre?tr('描述你的情况','Describe your experience'):tr('询问本次计划','Ask about your plan')}</label><textarea id="${which}-input" name="message" data-draft="${pre?'draftIntake':'draftPost'}" placeholder="${pre?tr('用你平常说话的方式写就好…','Write it the way you would say it…'):tr('还有哪里不清楚？也可以说说新的情况。','What is still unclear? You can also tell us what changed.')}" rows="2" maxlength="5000" ${busyAttr()}>${esc(value)}</textarea><div class="composer-bottom"><div class="compose-tools">${pre?`<button type="button" class="icon-button" data-action="upload" data-context="intake" aria-label="${tr('添加已有资料','Add an existing record')}" ${busyAttr()}>${icon('upload',17)}</button>`:''}<span class="composer-helper">${tr('由 DeepSeek 处理 · 请勿填写身份信息','Processed by DeepSeek · Omit identifying details')}</span></div><button type="submit" class="send-button" aria-label="${pre?tr('发送描述','Send description'):tr('发送问题','Send question')}" ${busyAttr()}>${icon('send',17)}</button></div></div>${pre?`<div class="chat-footer"><span>${state.intake.turn?tr(`已澄清 ${Math.min(state.intake.turn,6)} 轮 · 最多 6 轮`,`Clarified ${Math.min(state.intake.turn,6)} of 6 turns`):tr('不需要一次就说完整','You do not have to say everything at once')}</span><button type="button" class="button ghost small" data-action="finish-intake" ${!state.intake.messages.length||state.busy?'disabled':''}>${icon('pause',12)}${tr('先整理到这里','Summarize for now')}</button></div>`:''}</form>`;
}
function aidView(){
 const it=state.intake;if(!it.messages.length||it.ready)return '';
 const options=[...new Set([...(it.options||[]).slice(0,4),tr('记不清了','I’m not sure'),tr('先跳过','Skip for now')])];
 const choices=`<div class="aid-options">${options.map(v=>`<button data-action="clarify-option" data-value="${esc(v)}" ${busyAttr()}>${esc(v)}</button>`).join('')}</div>`;
 if(it.aid==='body_map')return `<div class="aid-box"><h3>${tr('可以选一个大致的位置','Choose an approximate area')}</h3><div class="body-aid"><svg class="body-silhouette" width="80" height="150" viewBox="0 0 80 155" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="40" cy="17" r="12"/><path d="M27 35h26l13 44-9 3-8-26v40l8 53H44l-4-42-4 42H23l8-53V56l-8 26-9-3 13-44z" fill="#eef6f1"/><rect x="32" y="60" width="16" height="14" rx="5" class="body-region"/><rect x="32" y="78" width="16" height="16" rx="5" class="body-region"/></svg><div class="aid-options">${[tr('上腹部','Upper abdomen'),tr('下腹部','Lower abdomen'),tr('胸口','Chest'),tr('其他位置','Somewhere else'),tr('位置说不准','I can’t locate it')].map(v=>`<button data-action="clarify-option" data-value="${esc(v)}" ${busyAttr()}>${esc(v)}</button>`).join('')}</div></div></div>`;
 if(it.aid==='timeline')return `<div class="aid-box"><h3>${tr('把时间串起来，大概也可以','Build a rough timeline')}</h3><form class="aid-form" data-form="timeline"><input class="field" name="onset" aria-label="${tr('什么时候开始','When it started')}" placeholder="${tr('什么时候开始？例如上周','When did it start? e.g. last week')}" maxlength="120"><input class="field" name="duration" aria-label="${tr('每次持续多久','How long each episode lasts')}" placeholder="${tr('每次多久？例如半小时','How long each time? e.g. 30 minutes')}" maxlength="120"><button class="button secondary small" type="submit" ${busyAttr()}>${tr('补充这段时间线','Add this timeline')}</button></form><div class="mt-10">${choices}</div></div>`;
 return `<div class="aid-box">${it.aid==='episode'?`<h3>${tr('回忆最近的一次，会更容易描述','Try recalling the most recent time')}</h3>`:''}${choices}</div>`;
}
function patientReview(){return `<section class="panel section-gap"><div class="panel-head"><div><h2>${tr('先看看，这是不是你的意思','Does this sound like what you meant?')}</h2><p>${tr('这里记录你的经历，医生会再核对医学表述。','These are your reported experiences. Your clinician verifies clinical wording.')}</p></div></div><div class="panel-body"><div class="summary-facts">${state.intake.facts.map((f,i)=>`<div class="summary-fact"><span class="key">${esc(f.label)}</span><span>${esc(f.value)} ${f.certainty==='uncertain'?`<span class="chip amber">${tr('不确定','Uncertain')}</span>`:''}</span><button class="icon-button" data-action="edit-fact" data-index="${i}" aria-label="${tr('更正','Edit')} ${esc(f.label)}">${icon('edit',14)}</button></div>`).join('')}</div><div class="review-status">${icon(state.intake.reviewed?'check':'info',15)}${state.intake.reviewed?tr('你已核对这些描述','You reviewed these descriptions'):tr('尚未由你确认；不会自动标记为已核对','Not yet reviewed by you')}</div><div class="mt-18 inline-actions"><button class="button primary" data-action="review-intake" ${busyAttr()}>${icon('check',15)}${tr('符合我的意思','This reflects my experience')}</button><button class="button secondary" data-action="show-brief" ${busyAttr()}>${tr('展示给医生','Show the clinician')}${icon('arrow',15)}</button></div></div></section>`;}
function livingNotePreview(phase){
 const facts=state.intake.facts.slice(0,4),pending=state.questions.filter(q=>q.status!=='answered');
 return `<section class="care-note"><div class="note-title"><h2>${icon('note',17)}${tr('我的小纸条','Your living note')}</h2><span class="chip teal">${tr('随对话更新','Updates with you')}</span></div><div class="note-section"><h3>${phase==='pre'?tr('已经说清楚的','What is clear so far'):tr('这次计划','This visit’s plan')}</h3>${phase==='pre'?(facts.length?facts.map(f=>`<div class="fact-row"><strong>${esc(f.label)}</strong><span class="fact-value">${esc(f.value)}</span><button class="fact-source" data-action="source" data-source="${esc(f.sourceId||'patient')}" data-quote="${esc(f.quote)}" aria-label="${f.sourceId&&f.sourceId!=='patient'?tr('查看资料原文','View record source'):tr('查看患者原话','View original words')}">${icon('source',12)}</button></div>`).join(''):`<p class="note-empty">${tr('你说过的重要细节，会在这里慢慢变清楚。','The important details will come together here as we talk.')}</p>`):`<ul class="note-list">${state.plan?.items.slice(0,5).map(i=>`<li>${esc(i.title)}${i.timing?' · '+esc(i.timing):''}</li>`).join('')||''}</ul>`}</div><div class="note-section waiting"><h3>${tr('还需要弄清楚的','Still to clarify')}</h3>${phase==='pre'?(state.intake.unknowns.length?`<ul class="note-list">${state.intake.unknowns.slice(0,4).map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:`<p class="note-empty">${tr('记不清的地方会保留下来。','Uncertainty stays visible.')}</p>`):(pending.length?`<ul class="note-list">${pending.slice(0,3).map(q=>`<li>${esc(q.text)}</li>`).join('')}</ul>`:`<p class="note-empty">${tr('新的问题会记在这里，带到下次咨询。','Open questions will stay here for your next conversation.')}</p>`)}</div>${phase!=='pre'?`<div class="note-section"><h3>${tr('已经核对的理解','Understanding checked')}</h3><p class="tiny">${Object.values(state.checks).filter(v=>v.status==='matched').length} ${tr('项已核对','items checked')} · ${tr('可选择跳过','always optional')}</p></div>`:''}<div class="progress-line"><span class="${state.intake.facts.length?'filled':''}"></span><span class="${state.plan?.reviewed?'filled':''}"></span><span class="${state.plan?'filled':''}"></span><span class="${state.questions.length?'filled':''}"></span></div></section>`;
}
function activityView(){return `<section class="activity-card"><div class="activity-label"><span>${tr('这一步做了什么','WHAT HAPPENED')}</span><button class="fact-source" data-action="activity" aria-label="${tr('查看活动记录','View activity')}">${icon('history',14)}</button></div>${state.activities.slice(0,4).map(a=>`<div class="activity-row"><span class="dot"></span><span>${esc(state.lang==='en'?a.en:a.zh)}</span><time>${esc(a.time)}</time></div>`).join('')||`<p class="note-empty">${tr('开始后，你会看到整理过程。','The steps will appear as you go.')}</p>`}</section>`;}
function doctorView(){
 return `${heading('YOUR VISIT RECORDS',tr('拍下医嘱，把后面几天接好。','Your instructions, ready for everyday life.'),tr('就诊结束后，由你上传处方、门诊记录或检查安排。医生不需要使用这个系统。','After your visit, add the prescription, visit note or test instructions yourself. Your clinician does not need to use this app.'),`<button class="button secondary heading-action" data-action="show-brief">${icon('user',15)}${tr('展示诊前摘要','Show your visit brief')}</button>`)}<div class="main-grid"><section class="panel"><div class="panel-head"><div class="panel-head-title"><span class="icon-box">${icon('upload')}</span><div><h2>${tr('上传、核对，再整理','Capture, check, then organize')}</h2><p>${tr('你的资料，由你确认','Your records, reviewed by you')}</p></div></div></div><div class="panel-body"><div class="capture-actions"><button class="file-drop" data-action="camera" ${busyAttr()}>${icon('camera',27)}<div><p>${tr('拍照识别医嘱','Photograph your instructions')}</p><small>${tr('手机可拍照；电脑可选择图片','Take a photo on mobile or choose an image')}</small></div></button><button class="button secondary" data-action="upload" data-context="plan" ${busyAttr()}>${icon('upload',18)}${tr('选择已有文件','Choose a file')}</button></div><p class="field-help">${tr('照片、TXT、DOCX 或文字版 PDF。照片先在本机识别，确认后的文字才用于整理。','Photos, TXT, DOCX or text-based PDF. Photos are read locally; confirmed text is used to build the plan.')}</p>${state.ocrPhotoMissing?`<div class="warning-box">${tr('识别文字已恢复，照片未保存在浏览器中。请在手机或原文件中重新对照原图，再勾选确认；也可以重新选择照片。','Recognized text was restored; original photos were not stored. Recheck your phone or original file before confirming, or select the photo again.')}</div>`:''}${state.photoPreviews.map(photo=>`<figure class="photo-review"><img src="${esc(photo.url)}" alt="${esc(photo.title)}"><figcaption>${esc(photo.title)} · ${tr('对照照片检查药名、剂量、频率、疗程和日期','Compare names, doses, schedules, durations and dates with the photo')}</figcaption></figure>`).join('')}${state.busy==='upload'?loading(tr('正在识别资料…','Reading your document…')):''}<div class="divider-label">${tr('识别结果 / 也可以直接粘贴原文','Recognized text / or paste the original')}</div><form data-form="plan"><label class="field-label" for="record-text">${tr('我的医嘱原文','My original instructions')}</label><textarea id="record-text" class="field record-text" data-draft="draftPlanText" maxlength="30000" placeholder="${tr('拍照后在这里核对，也可以直接粘贴。','Review recognized text here, or paste your instructions.')}" ${busyAttr()}>${esc(state.draftPlanText)}</textarea>${state.ocrPending?`<label class="review-status"><input type="checkbox" id="ocr-reviewed" ${state.ocrReviewed?'checked':''} required>${tr('我已对照照片，核对关键用药与时间信息','I checked important medicine details and dates against the photo')}</label>`:''}<div class="field-help">${tr('资料没有写明的会保留为待确认，不补写医嘱。','Missing instructions stay open for clarification.')}</div><div class="mt-18 inline-actions"><button type="submit" class="button primary" ${busyAttr()}>${state.busy==='plan'?'<span class="spinner"></span>':icon('spark',16)}${tr('整理我的行动清单','Build my care plan')}</button><button type="button" class="button ghost" data-action="fill-record" ${busyAttr()}>${tr('填入虚构示例','Use a fictional record')}</button></div></form></div></section><aside class="right-stack"><div class="capture-steps"><h3>${tr('这一步，怎么用','How this works')}</h3><ol><li>${tr('把医生给你的资料拍清楚','Photograph the instructions clearly')}</li><li>${tr('核对识别文字，改正看错的地方','Check the recognized text and correct errors')}</li><li>${tr('生成行动清单，再设置自己的提醒','Build your plan, then set your reminders')}</li></ol></div>${livingNotePreview(state.plan?'post':'pre')}${activityView()}</aside></div>`;
}
function showBrief(){openModal(tr('给医生看的简短摘要','A brief to show your clinician'),`<p class="field-help">${tr('由患者整理并展示 · 不需要医生登录','Prepared and shown by the patient · No clinician login')}</p><div class="source-text brief-display">${esc(briefText())}</div><div class="inline-actions"><button class="button primary" data-action="copy-brief">${icon('copy',15)}${tr('复制摘要','Copy brief')}</button><button class="button secondary" data-action="continue-records">${tr('就诊结束，加入医嘱','After the visit, add instructions')}${icon('arrow',15)}</button></div>`);}
function reminderPanel(){
 const current=state.reminders.filter(r=>r.version===state.plan?.version),stale=state.reminders.length-current.length;
 return `<section class="panel reminder-panel"><div class="panel-head"><div class="panel-head-title"><span class="icon-box">${icon('calendar')}</span><div><h2>${tr('把计划放进生活里','Make room for your plan')}</h2><p>${tr('用药 · 检查 · 复诊提醒','Medication · tests · follow-up')}</p></div></div></div><div class="panel-body">${current.length?`<div class="reminder-list">${current.map(r=>`<div class="reminder-row"><span class="reminder-time">${esc(r.start.slice(11,16))}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.start.slice(0,10))} · ${r.count}${tr('天',' days')} · ${esc(r.timeZone)}</p><span class="chip ${r.synced?'teal':''}">${r.synced?tr('已写入 Google','Saved to Google'):tr('已设置 · 待加入日历','Set · add to calendar')}</span></div></div>`).join('')}</div>`:`<p class="muted tiny">${tr('在行动卡片上点“设置提醒”，选择与你生活节奏匹配的时间。','Choose “Set reminder” on an action card, then pick a time that fits your day.')}</p>`}${stale?`<p class="warning-box">${tr('计划已更新。旧版提醒需重新核对；已导出的日历不会自动修改，请在日历中删除或更正旧提醒。','The plan changed. Recheck older reminders and remove or edit previously exported calendar events yourself.')}</p>`:''}<button class="button primary wide mt-15" data-action="calendar-manager">${icon('calendar',15)}${tr('日历与提醒','Calendar & reminders')}</button><p class="field-help">Google Calendar · Apple Calendar · .ics</p></div></section>`;
}
function reminderDialog(id){
 const item=state.plan?.items.find(i=>i.id===id);if(!item)return;
 if(!state.plan.reviewed){notify(tr('先点击“已核对原文”，确认计划内容后再设置提醒。','Check the source plan before scheduling reminders.'));return;}
 const med=item.kind==='medication',frequency=med?dailyFrequency(item.frequency):1,days=med?durationDays(item.duration):1;
 if(med&&(!item.dose||!frequency||!days||days>90||conditionalSchedule(item.sourceQuote))){openModal(tr('先把执行方式确认清楚','Clarify the instructions first'),`<p>${tr('这份医嘱不适合直接生成每日提醒。请先确认用量、每日次数和疗程；按需或间隔用药暂不自动排期。','This instruction cannot be safely turned into daily reminders yet. Confirm the dose, daily frequency and duration first. As-needed or interval schedules are not automatically scheduled.')}</p><div class="source-text">${esc(item.sourceQuote)}</div>`);return;}
 const zone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai';
 openModal(tr('设置这一步的提醒','Schedule this step'),`<h3>${esc(item.title)}</h3><p class="reminder-source">${esc(item.sourceQuote)}</p><form data-form="reminder" data-id="${esc(id)}"><div class="form-grid"><div><label class="field-label" for="reminder-date">${med?tr('开始服用的日期','First day'):tr('预约日期','Appointment date')}</label><input id="reminder-date" name="date" class="field" type="date" required></div><div><label class="field-label" for="reminder-days">${tr('提醒天数（来自医嘱）','Number of days (from instructions)')}</label><input id="reminder-days" name="days" class="field" type="number" value="${days}" readonly></div></div><label class="field-label" for="reminder-times">${med?tr(`每天 ${frequency} 个提醒时间`,`Choose ${frequency} reminder time(s) each day`):tr('预约时间','Appointment time')}</label><input id="reminder-times" name="times" class="field" required placeholder="${frequency===2?'08:00, 20:00':'09:00'}"><p class="field-help">${tr('使用24小时制，多个时间用逗号分隔。时钟提醒由你设置，仍须遵守原文的饭前、饭后等要求。','Use 24-hour time, separated by commas. These are times you choose; follow the original instructions about meals and timing.')}</p><label class="field-label" for="reminder-zone">${tr('提醒使用的时区','Reminder time zone')}</label><input id="reminder-zone" name="zone" class="field" value="${esc(zone)}" list="time-zones" required><datalist id="time-zones"><option value="Asia/Shanghai"><option value="America/Los_Angeles"><option value="America/New_York"><option value="Europe/London"></datalist><label class="review-status"><input type="checkbox" name="confirmed" required>${tr('我已对照医嘱，确认日期、时区与提醒时间','I checked the dates, timezone and reminder times against my instructions')}</label><button class="button primary mt-15" type="submit">${tr('保存提醒设置','Save reminder settings')}</button></form>`);
}
function saveReminder(id,data){
 const item=state.plan.items.find(i=>i.id===id),frequency=item.kind==='medication'?dailyFrequency(item.frequency):1;
 const times=String(data.get('times')).split(/[,，]/).map(x=>x.trim());
 if(times.length!==frequency||new Set(times).size!==times.length){notify(tr(`请填写 ${frequency} 个不同的提醒时间。`,`Enter ${frequency} distinct reminder times.`));return;}
 const reminders=times.map(clock=>({id:uid(),itemId:id,version:state.plan.version,title:item.title,description:item.sourceQuote,start:`${data.get('date')}T${clock}:00`,timeZone:String(data.get('zone')),count:Number(data.get('days')),minutesBefore:item.kind==='medication'?0:30,kind:item.kind,synced:false}));
 try{validateReminders(reminders);}catch(e){notify(tr('请检查日期、时间和时区，时间请写成 08:00。','Check the date and timezone; use a time such as 08:00.'));return;}
 if(state.reminders.some(r=>r.itemId===id&&r.version===state.plan.version)){notify(tr('此项已有提醒。请在“日历与提醒”中先移除旧设置，再重新设置。','This item already has reminders. Remove its settings in Calendar & reminders first.'));return;}
 state.reminders.push(...reminders);activity('患者确认提醒时间；尚未写入日历','Patient confirmed reminder times; calendar not written');closeModal();render();notify(tr('提醒设置已保存。加入日历后由日历应用通知你。','Reminder times saved. Add them to a calendar for notifications.'));
}
async function calendarRequest(path,body){const res=await fetch(path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(65000)});const result=await res.json();if(!res.ok||!result.ok)throw new Error(result.error?.message||'Calendar request failed.');return result;}
async function calendarManager(refresh=true){
 if(refresh){try{state.calendar=await calendarRequest('/api/calendar/status');}catch(e){notify(e.message);}}
 const current=state.reminders.filter(r=>r.version===state.plan?.version),c=state.calendar;
 openModal(tr('日历与提醒','Calendar & reminders'),`<div class="calendar-connect"><span class="google-mark">G</span><div><h3>Google Calendar</h3><p>${c?.connected?tr('已连接当前 Google 账户','Connected to your Google account'):c?.configured?tr('接口已配置 · 等待你连接账户','Interface configured · connect your account'):tr('接口已就绪 · 尚未配置账户连接','Interface ready · account connection not configured')}</p></div><span class="chip ${c?.connected?'teal':'amber'}">${c?.connected?tr('已连接','Connected'):tr('未连接','Not connected')}</span></div><div class="inline-actions mt-15"><button class="button secondary" data-action="connect-calendar">${tr('连接 Google Calendar','Connect Google Calendar')}</button><button class="button ghost" data-action="refresh-calendar">${tr('刷新连接状态','Refresh connection')}</button>${c?.connected?`<button class="button ghost" data-action="disconnect-calendar">${tr('断开本次连接','Disconnect this session')}</button>`:''}</div><div class="divider"></div><h3>${tr('将加入日历的提醒','Reminders to add')}</h3>${current.length?`<div class="calendar-preview">${current.map(r=>`<div class="reminder-row"><span class="reminder-time">${esc(r.start.slice(11,16))}</span><div><strong>${esc(r.title)}</strong><p>${esc(r.start.slice(0,10))} · ${r.count}${tr('天',' days')} · ${esc(r.timeZone)}</p><span>${r.synced?tr('已写入 Google','Saved to Google'):tr('尚未写入 Google','Not saved to Google')}</span></div><button class="icon-button" data-action="remove-reminder" data-id="${esc(r.id)}" aria-label="${tr('移除提醒设置','Remove reminder setting')}">${icon('close',14)}</button></div>`).join('')}</div><label class="review-status"><input type="checkbox" id="calendar-details">${tr('在日历中包含药名和医嘱文字（默认只显示通用提醒）','Include medicine names and instructions in the calendar (generic reminders by default)')}</label><div class="inline-actions mt-15"><button class="button primary" data-action="sync-calendar" ${c?.connected?'':'disabled'}>${tr('确认并写入 Google Calendar','Confirm & save to Google Calendar')}</button><button class="button secondary" data-action="export-calendar">${icon('down',15)}${tr('下载提醒日历 .ics','Download reminders .ics')}</button></div>`:`<p class="muted mt-15">${tr('还没有当前计划的提醒。回到行动卡片，选择“设置提醒”。','No reminders for this plan yet. Choose “Set reminder” on an action card.')}</p>`}<p class="modal-note">${tr('下载后请在日历应用中导入，并检查通知权限与提醒设置。AfterDoc 本身不会在页面关闭后推送通知。修改或移除这里的设置不会删除已导出的日历活动。','Import the file into your calendar and check notification settings. AfterDoc does not send background notifications when the page is closed. Removing these settings does not delete events already exported to a calendar.')}</p>`);
}
async function connectCalendar(){
 if(!state.calendar?.configured){openModal(tr('Google Calendar 接口配置','Google Calendar interface setup'),`<p>${tr('接口已经实现。配置本地 OAuth 应用后，患者即可自行连接账户。','The integration endpoints are implemented. Configure a local OAuth app so patients can connect their own account.')}</p><div class="source-text">GOOGLE_CLIENT_ID\nGOOGLE_CLIENT_SECRET\nGOOGLE_REDIRECT_URI=http://127.0.0.1:4173/api/calendar/google/callback</div><p class="modal-note">${tr('由开发者把配置放入本地 .env，启用 Google Calendar API 并重启服务。无需在对话中发送密钥。','A developer adds these to the local .env, enables the Google Calendar API and restarts the server. Do not share credentials in chat.')}</p><button class="button secondary" data-action="refresh-calendar">${tr('返回提醒','Back to reminders')}</button>`);return;}
 try{const result=await calendarRequest('/api/calendar/google/authorize',{});if(!result.url.startsWith('https://accounts.google.com/'))throw new Error('Unexpected authorization destination');openModal(tr('连接你的 Google Calendar','Connect your Google Calendar'),`<p>${tr('在 Google 页面选择账户并授权。连接后回到这里，刷新连接状态。尚未写入任何活动。','Choose an account and authorize on Google. Return here and refresh the connection. No event has been written yet.')}</p><a class="button primary mt-15" href="${esc(result.url)}" target="_blank" rel="noopener noreferrer">${tr('前往 Google 授权','Continue to Google')}</a><button class="button secondary mt-15" data-action="refresh-calendar">${tr('刷新连接状态','Refresh connection')}</button>`);}catch(e){notify(e.message);}
}
async function exportCalendar(){const events=state.reminders.filter(r=>r.version===state.plan?.version);if(!events.length)return;await offerDownload({type:'calendar',events,includeDetails:Boolean($('#calendar-details')?.checked)});}
async function offerDownload(payload){try{const result=await calendarRequest('/api/exports',payload);openModal(tr('导出文件已准备好','Your export is ready'),`<p>${payload.type==='backup'?tr('此备份包含已保存的就诊、版本和来源，请保存在自己的安全位置。当前原型没有导入备份的界面。','This backup contains saved visits, versions and sources. Keep it somewhere private. This prototype has no backup-import interface.'):tr('点击下面的链接保存文件。日历文件导入后，请检查通知设置。','Use the link below to save your file. After importing calendar events, check notification settings.')}</p><a class="button primary mt-15 download-link" href="${esc(result.url)}" download="${esc(result.filename)}">${icon('down',16)}${esc(result.filename)}</a><p class="modal-note">${tr('链接仅在本机有效，10分钟后过期。','This local download link expires in 10 minutes.')}</p>`);activity('导出文件已准备好，等待下载','Prepared an export for download');}catch(e){notify(e.message);}}

async function syncCalendar(){const events=state.reminders.filter(r=>r.version===state.plan?.version),includeDetails=Boolean($('#calendar-details')?.checked);closeModal();await run('calendar',async()=>{const result=await calendarRequest('/api/calendar/google/events',{events,includeDetails,confirmed:true});for(const saved of result.results||[]){const reminder=state.reminders.find(r=>r.id===saved.id);if(reminder&&saved.ok)reminder.synced=true;}activity(result.allSaved?'提醒已写入 Google Calendar':'部分提醒未写入，保留结果以便重试',result.allSaved?'Saved reminders to Google Calendar':'Some reminders were not saved; results retained');if(!result.allSaved)throw new Error(tr('部分提醒没有保存成功，可以重新尝试，已成功的不会重复创建。','Some reminders could not be saved. Retry will not duplicate successfully created events.'));notify(tr('提醒已写入 Google Calendar。','Reminders saved to Google Calendar.'));});await calendarManager();}

function afterView(){
 if(!state.plan)return `${heading('AFTER YOUR VISIT',tr('接下来，该怎么做？','What happens after the visit?'),tr('从本次医生的书面计划开始。','Begin with the clinician’s written plan.'))}<section class="panel empty-state"><div class="large-icon">${icon('note',32)}</div><h2>${tr('先放进这次就诊的资料','Add this visit’s records')}</h2><p>${tr('把处方、门诊记录或检查安排放在一起，我们再把每一步整理清楚。','Bring together the prescription, visit note or test instructions, then turn them into clear next steps.')}</p><div class="justify-center inline-actions"><button class="button primary" data-action="view" data-view="doctor">${icon('upload',16)}${tr('加入资料','Add records')}</button><button class="button secondary" data-action="demo">${tr('体验虚构病例','Try the fictional case')}</button></div></section>`;
 const c=state.plan.complexity||{level:'low',reasons:[]};
 return `${heading('AFTER YOUR VISIT',tr('看懂计划，安心往下走。','A clear plan for what comes next.'),tr('关键安排始终在这里。解释多少，由你来选。','Your essential steps stay visible. You choose how much explanation to receive.'),`<button class="button secondary heading-action" data-action="view" data-view="note">${icon('note',15)}${tr('查看我的小纸条','Open your living note')}</button>`)}<div class="preference-bar"><div class="preference-copy">${tr('这一次，你希望我怎么帮你？','How much support would you like right now?')}</div><div class="segmented" role="group" aria-label="${tr('解释深度','Explanation depth')}"><button data-action="preference" data-value="brief" class="${state.preference==='brief'?'active':''}" aria-pressed="${state.preference==='brief'}">${tr('告诉我怎么做','Just the next steps')}</button><button data-action="preference" data-value="detail" class="${state.preference==='detail'?'active':''}" aria-pressed="${state.preference==='detail'}">${tr('我想多了解一些','Help me understand more')}</button></div></div><div class="main-grid"><div>${!state.plan.reviewed?`<div class="mb-18 info-line amber">${icon('info',17)}<div>${tr('这是根据资料整理的草稿。点开“原文”核对关键用药和时间信息。','This is a draft extracted from your records. Check important doses and dates against the source.')}<div class="mt-8"><button class="button secondary small" data-action="confirm-plan">${tr('已核对原文','I checked the source')}</button></div></div></div>`:''}<div class="plan-header"><h2>${tr('本次行动清单','Your action list')}</h2><div class="inline-actions"><span class="chip">V${state.plan.version||1}</span>${state.demo?`<span class="chip amber">${tr('虚构演示医嘱','Fictional demo record')}</span>`:''}<button class="source-link" data-action="source" data-source="${esc(state.documents[0]?.id||'')}" data-quote="">${icon('source',12)}${tr('全部原文','Full record')}</button></div></div>${c.reasons?.length?`<div class="complexity"><div class="complexity-head">${icon('info',15)}${tr('这份计划有几处值得多看一眼','A few details deserve an extra look')}</div><p>${esc(c.reasons.join(' · '))}</p><p>${tr('我们据此提供帮助，但不会强迫你逐项测验。','We use this to offer support. You do not have to take a quiz.')}</p></div>`:''}<div class="care-items">${state.plan.items.map(careItem).join('')}</div>${state.plan.warnings?.length?`<div class="warning-box"><strong>${icon('shield',14)}${tr('原记录中的提醒','Reminders in the original record')}</strong>${state.plan.warnings.map(w=>`<div>${esc(typeof w==='string'?w:w.text||w.message||'')}</div>`).join('')}</div>`:''}${state.busy==='calendar'?loading(tr('正在保存日历提醒…','Saving calendar reminders…')):''}<div class="completion-bar"><span>${Object.values(state.completed).filter(Boolean).length} / ${state.plan.items.length} ${tr('项安排已记下 · 由患者标记','arrangements noted · patient reported')}</span><button class="button ghost small" data-action="view" data-view="doctor">${tr('更新原始资料','Update the source record')}</button></div><section class="panel post-chat"><div class="panel-head"><div class="panel-head-title"><span class="icon-box">${icon('chat')}</span><div><h2>${tr('还有问题，接着问。','Keep the conversation going.')}</h2><p>${tr('解释原计划，也记下需要医生回答的问题。','Understand the plan and save questions for your clinician.')}</p></div></div></div><div class="conversation" role="log" aria-live="polite">${messageView({role:'assistant',content:tr('你可以问得简短，也可以反复问。我会对照本次资料；资料没写的，或需要新判断的，会单独记下来。','Ask as briefly or as often as you need. I will refer to your records and keep missing answers or new clinical decisions separate.')})}${state.postMessages.map(messageView).join('')}</div>${state.busy==='post'?loading(tr('正在对照医嘱与问题…','Checking the question against your records…')):''}${composer('post')}</section></div><aside class="right-stack">${reminderPanel()}${livingNotePreview('post')}${pendingPreview()}${activityView()}</aside></div>`;
}
function careItem(item){
 const check=state.checks[item.id],done=state.completed[item.id];
 const dose=[item.dose,item.frequency,item.duration].filter(Boolean).join(' · ');
 return `<article class="care-item ${esc(item.kind)}" data-item-id="${esc(item.id)}"><div class="care-item-top"><span class="item-icon">${icon(item.kind==='medication'?'pill':item.kind==='test'?'test':item.kind==='followup'?'calendar':'note',21)}</span><div class="item-heading"><h3>${esc(item.title)}</h3><p class="item-meta">${kindName(item.kind)}${done?' · '+tr('已记下','Noted'):''}</p></div><button class="item-check ${done?'done':''}" data-action="toggle-item" data-id="${esc(item.id)}" aria-label="${tr('标记已记下：','Mark as noted: ')}${esc(item.title)}" aria-pressed="${!!done}" title="${tr('我已记下这个安排','I have noted this arrangement')}">${done?icon('check',14):''}</button></div>${dose?`<div class="dose-line">${esc(dose)}</div>`:''}${item.timing||item.kind==='medication'?`<div class="timing-line">${icon('clock',14)}<span>${esc(item.timing||tr('时间未记载','Timing not recorded'))}</span></div>`:''}<p class="essential-directions">${esc(item.sourceQuote||item.details)}</p>${item.missing?.length?`<div class="missing-line">${icon('question',13)}${tr('尚未明确：','Not yet specified: ')}${esc(item.missing.map(missingName).join(' · '))}</div>`:''}${state.preference==='detail'?`<div class="item-detail"><strong>${tr('用日常的话说','In everyday words')}</strong>${esc(item.explanation||item.details)}<p class="detail-caption">${tr('以上是对原文的解释；具体治疗选择的理由须以医生说明为准。','This explains the record; the reason for choosing treatment must come from your clinician.')}</p></div>`:''}<div class="item-footer">${sourceButton(item.sourceId,item.sourceQuote)}${['medication','test','followup'].includes(item.kind)?`<button class="source-link" data-action="reminder" data-id="${esc(item.id)}" ${busyAttr()}>${icon('calendar',12)}${tr('设置提醒','Set reminder')}</button>`:''}${check?.status==='matched'?`<span class="chip teal">${icon('check',11)}${tr('本条理解已核对','Understanding checked')}</span>`:check?.status==='skipped'?`<span class="chip">${tr('已跳过核对','Check skipped')}</span>`:`<button class="button ghost small" data-action="open-check" data-id="${esc(item.id)}" ${busyAttr()}>${item.id===priorityItem()?tr('这项可优先核对','Suggested check'):tr('按需核对理解','Check if helpful')}</button>`}</div>${state.checkOpen===item.id?checkView(item):''}</article>`;
}
function checkQuestion(item){return item.kind==='medication'?tr(`按这份医嘱，你打算怎么服用「${item.title}」？可以说说每次用量、每天几次和持续几天。`,`According to this record, how will you take ${item.title}? Include the amount each time, how often, and for how long.`):tr(`关于「${item.title}」，你接下来准备做什么？`,`For “${item.title}”, what will you do next?`);}
function checkView(item){const check=state.checks[item.id];return `<div class="check-box">${state.busy==='check'?loading(tr('正在对照原文核对…','Checking against the source…')):''}<h3>${tr('用你自己的话说说就好','Say it in your own words')}</h3><p>${esc(checkQuestion(item))}</p>${check&&check.status!=='skipped'?`<div class="check-result" role="status"><span class="chip ${check.status==='matched'?'teal':'amber'}">${check.status==='matched'?tr('与本条医嘱一致','Matches this instruction'):check.status==='mismatch'?tr('还有一处需要澄清','One detail needs another look'):tr('暂时无法确认','Not confirmed yet')}</span><div>${esc(check.reply)}</div></div>`:''}${check?.attempts>=2&&check.status!=='matched'?`<p>${tr('我们先停在这里。这一项会保留为待澄清，不需要反复答题。','Let’s pause here. This stays unresolved; you do not need to keep answering.')}</p><button class="button secondary small" data-action="skip-check" data-id="${esc(item.id)}">${tr('先保留这个疑问','Keep it open')}</button>`:check?.status==='matched'?`<button class="button secondary small" data-action="close-check">${tr('知道了','Got it')}</button>`:`<form data-form="check" data-id="${esc(item.id)}"><textarea class="field" name="answer" data-draft="draftCheck" aria-label="${tr('描述你对这项医嘱的理解','Describe your understanding')}" maxlength="2000" placeholder="${tr('我准备…','I plan to…')}" ${busyAttr()}>${esc(state.draftCheck)}</textarea><div class="mt-10 inline-actions"><button class="button primary small" type="submit" ${busyAttr()}>${tr('核对这一步','Check this step')}</button><button class="button ghost small" type="button" data-action="skip-check" data-id="${esc(item.id)}" ${busyAttr()}>${tr('跳过 / 还不确定','Skip / not sure')}</button></div></form>`}</div>`;}
function pendingPreview(){const pending=state.questions.filter(q=>q.status!=='answered');if(!pending.length)return `<div class="help-card"><h3>${tr('解释与决策，分开处理','Explanation and decisions')}</h3><p>${tr('想了解原文，我们一起看。需要改变用药、出现新的不适，或原文没有答案，会整理为待咨询的问题。','We can look at the written plan together. Treatment changes, new symptoms and missing instructions are kept for professional input.')}</p></div>`;return `<section><div class="activity-label"><span>${tr('待专业人员确认','FOR PROFESSIONAL INPUT')}</span><span class="chip amber">${pending.length}</span></div>${pending.slice(0,3).map(questionCard).join('')}</section>`;}
function questionCard(q){return `<article class="question-card ${q.route==='clinical_review'?'clinical':''}"><div class="question-meta"><span class="chip ${q.status==='answered'?'teal':routeClass(q.route)}">${q.status==='answered'?tr('患者标记已解决','Patient marked resolved'):q.status==='replied'?tr('已记录回复 · 仍待确认','Reply recorded · still open'):q.status==='sent'?tr('患者标记已发出','Patient marked sent'):tr('已保存 · 未发送','Saved · not sent')}</span><span>${esc(q.time)}</span></div>${q.origin?`<button class="source-link" data-action="archived-visit" data-visit="${esc(q.origin.visitId)}">${tr('来自第','From visit ')}${q.origin.visitNumber}${tr('次就诊','')} · ${tr('查看当时记录','View original visit')}</button>`:''}<p class="question-title">${esc(q.text)}</p>${q.reply?`<div class="reply-text">${esc(q.reply)}<div class="field-help">${esc(q.replySource||'')} · ${tr('由用户录入，未核验身份','Entered by the user; identity not verified')}</div></div>`:''}<div class="inline-actions">${q.status!=='answered'?`<button class="button secondary small" data-action="record-reply" data-id="${esc(q.id)}">${tr('记录专业回复','Record a professional reply')}</button>${q.status==='saved'?`<button class="button ghost small" data-action="mark-sent" data-id="${esc(q.id)}">${tr('我已自行发出','I sent it myself')}</button>`:''}`:''}</div></article>`;}
function noteView(){
 const answered=state.questions.filter(q=>q.status==='answered'),pending=state.questions.filter(q=>q.status!=='answered');
 return `${heading('YOUR LIVING NOTE',tr('下一次，不必从头说起。','Next time, pick up where you left off.'),tr('把原计划、期间的变化和未解的问题，带到下一次咨询。','Bring the original plan, what changed, and the open questions to your next conversation.'),`<div class="inline-actions heading-action"><button class="button secondary" data-action="copy-note">${icon('copy',15)}${tr('复制','Copy')}</button><button class="button primary" data-action="export-note">${icon('down',15)}${tr('导出小纸条','Export your note')}</button></div>`)}${noteVersionBar()}<div class="main-grid"><section class="panel return-note"><div class="note-document-header"><div><div class="eyebrow">${visitLabel(state.visit.number)} / ${tr('当前小纸条','WORKING NOTE')}</div><h2>${tr('给下一次就诊的小纸条','A note for the next visit')}</h2><p>${state.demo?tr('林女士 · 虚构演示病例','Ms Lin · Fictional case'):tr('当前会话 · 身份信息未填写','Current session · No identifying details')} · ${new Date().toLocaleDateString(state.lang==='en'?'en-US':'zh-CN')}</p></div>${icon('note',29)}</div><div class="stat-row"><div class="stat"><b>${state.plan?.items.length||0}</b><span>${tr('原计划事项','Plan items')}</span></div><div class="stat"><b>${Object.values(state.checks).filter(c=>c.status==='matched').length}</b><span>${tr('已核对的理解','Understanding checks')}</span></div><div class="stat"><b>${pending.length}</b><span>${tr('待专业确认','Open questions')}</span></div></div>${carryoverPanel(true)}<section class="note-document-section"><h3><span>01</span>${tr('患者原本想说什么','What the patient reported')}</h3>${state.intake.facts.length?`<ul>${state.intake.facts.map(f=>`<li><strong>${esc(f.label)}：</strong>${esc(f.value)}</li>`).join('')}</ul>`:`<p class="muted">${tr('本次会话未收集诊前描述。','No pre-visit history collected in this session.')}</p>`}<p class="field-help">${state.intake.reviewed?tr('患者已核对描述。','Patient reviewed the descriptions.'):tr('患者尚未核对描述。','Descriptions not reviewed by the patient.')}</p></section><section class="note-document-section"><h3><span>02</span>${tr('医生原计划与患者标记','The documented plan and patient updates')}</h3>${state.plan?`<ul>${state.plan.items.map(i=>`<li>${esc(i.title)} · ${esc([i.dose,i.frequency,i.duration,i.timing].filter(Boolean).join(' / '))}<br><span class="muted tiny">${state.completed[i.id]?tr('患者已标记记下安排','Patient marked this arrangement as noted'):tr('未标记完成','No completion reported')} · ${state.checks[i.id]?.status==='matched'?tr('本条理解已核对','Understanding checked'):tr('理解尚未确认','Understanding not confirmed')}</span></li>`).join('')}</ul>`:`<p class="muted">${tr('尚未加入诊后计划。','No post-visit plan added yet.')}</p>`}</section><section class="note-document-section"><h3><span>03</span>${tr('期间提出的问题与新情况','Questions and changes during the interval')}</h3>${state.postMessages.filter(m=>m.role==='user').length?`<ul>${state.postMessages.filter(m=>m.role==='user').map(m=>`<li>${esc(m.content)}</li>`).join('')}</ul>`:`<p class="muted">${tr('暂未记录。','Nothing recorded yet.')}</p>`}</section><section class="note-document-section"><h3><span>04</span>${tr('患者标记已经解决的','Marked resolved by the patient')}</h3>${answered.map(questionCard).join('')||`<p class="muted">${tr('暂无标记已解决的问题。','No question has been marked resolved yet.')}</p>`}</section><section class="note-document-section"><h3><span>05</span>${tr('仍需要专业人员确认的','Still needing professional input')}</h3>${pending.map(questionCard).join('')||`<p class="muted">${tr('暂无待确认问题。','No open professional questions yet.')}</p>`}</section><div class="divider"></div><p class="field-help">${tr('这份小纸条是沟通辅助材料。来源、未确认状态与用户标记均予以保留。','This note supports communication. Sources, uncertainty and patient-reported status are retained.')}</p></section><aside class="right-stack">${noteHistoryPanel()}<div class="care-note"><div class="note-title"><h2>${icon('history',17)}${tr('本次医嘱版本','This visit’s plan versions')}</h2></div>${state.versions.length?state.versions.map(v=>`<button class="plan-version version-button" data-action="version" data-version="${v.version}"><span>V${v.version} · ${esc(v.label)}</span><span class="muted tiny">${esc(v.time)} ↗</span></button>`).join(''):`<p class="note-empty">${tr('加入计划后显示版本。','Versions appear after a plan is added.')}</p>`}<p class="field-help">${tr('新回复会保留来源。用药变更须有完整的新医嘱。','New replies retain their source. A treatment change requires a complete new plan.')}</p></div><div class="help-card"><h3>${tr('有来有回的小纸条','A note that carries the conversation')}</h3><p>${tr('“保存了问题”不代表已经联系医生。这里明确区分已保存、患者自行发出、已记录回复。','Saving a question does not contact a clinician. Saved, patient-sent and reply-recorded states stay separate.')}</p></div>${activityView()}</aside></div>`;
}

async function agent(task,payload){
 const response=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task,language:state.lang,payload}),signal:AbortSignal.timeout(65000)});
 const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.error?.message||tr('请求没有完成，请重试。','The request did not complete. Please try again.'));
 state.lastMeta=data.meta;return data.result;
}
async function run(scope,operation,retry){if(state.busy)return;state.busy=scope;state.error=null;retryAction=null;render();try{await operation();}catch(e){state.error=e.name==='TimeoutError'?tr('等待模型回复超时。你的输入仍在当前会话中，可以重试。','The model timed out. Your input is still in this session. Try again.'):e.message;retryAction=retry;activity('这一步未完成，保留输入','Step incomplete; input retained');}finally{state.busy='';render();}}
async function sendIntake(input,finish=false,retry=false,recordNotice=false){
 const content=input.trim();if(!finish&&!content)return;
 if(!retry&&content){state.intake.messages.push({role:'user',content,...(recordNotice?{kind:'record'}:{})});if(!recordNotice)state.intake.turn++;markPatientCorrection(state);state.draftIntake='';}
 await run('intake',async()=>{
   activity('整理患者原话','Organizing the patient’s words');
   const result=await agent('intake',{messages:state.intake.messages.map(m=>({role:m.role,content:m.content,...(m.kind?{kind:m.kind}:{})})),records:state.intake.records,facts:state.intake.facts,previousVisit:previousVisitContext(state),turn:state.intake.turn,finish:finish||state.intake.turn>=6});
   state.intake.facts=result.facts||[];state.intake.unknowns=result.unknowns||[];state.intake.aid=result.aid||'open_question';state.intake.question=result.question||'';state.intake.options=result.options||[];state.intake.ready=Boolean(result.ready||finish||state.intake.turn>=6);
   let text=result.reply||'';if(result.question&&!state.intake.ready&&!text.includes(result.question))text+='\n\n'+result.question;
   state.intake.messages.push({role:'assistant',content:text});
   const aidNames={body_map:['选择位置辅助','Selected a body-location aid'],timeline:['选择时间线辅助','Selected a timeline aid'],episode:['聚焦最近一次经历','Focused on one recent episode'],record:['使用患者提供的资料','Used the supplied record'],summary:['生成可核对的摘要','Prepared a reviewable summary'],open_question:['选择一个澄清问题','Selected one clarification question']};
   activity(...(aidNames[state.intake.ready?'summary':state.intake.aid]||aidNames.open_question));
 },()=>sendIntake(content,finish,true,recordNotice));
}
async function extractPlan(text,retry=false){
 if(state.ocrPending&&!state.ocrReviewed){notify(tr('先对照照片核对识别文字。','Check the recognized text against your photo first.'));return;}
 if(!text.trim()){notify(tr('先加入一段医生原文。','Add the original clinician record first.'));return;}
 const doc={id:uid(),title:tr('本次门诊资料','Visit record'),text:text.trim()};
 await run('plan',async()=>{
   activity('提取医嘱并核对每条来源','Extracting instructions and checking sources');
   const result=await agent('extract_plan',{documents:[doc],previousPlan:state.plan});
   if(!Array.isArray(result.items)||!result.items.length)throw new Error(tr('没有找到可引用的计划事项，请检查原文。','No source-linked plan items found. Check the record.'));
   Object.assign(state,addPlanVersion(state,result,[doc],{label:tr('完整书面计划','Complete written plan'),time:time()}));state.checks={};state.completed={};state.checkOpen=null;state.view='after';
   activity(`生成 ${result.items.length} 条有来源的安排`,`Created ${result.items.length} source-linked plan items`);
 },()=>extractPlan(text,true));
}
async function askPlan(question,retry=false){
 const text=question.trim();if(!text||!state.plan)return;
 if(!retry){state.postMessages.push({role:'user',content:text});state.draftPost='';}
 await run('post',async()=>{
   activity('对照本次资料回答问题','Checking the question against visit records');
   const result=await agent('ask_plan',{question:text,preference:state.preference,plan:state.plan,documents:state.documents,messages:state.postMessages.slice(-14).map(m=>({role:m.role,content:m.content}))});
   state.postMessages.push({role:'assistant',content:result.reply,route:result.route,citations:result.citations||[]});
   if(result.route!=='explanation'){
     const q=result.questionForClinician||text;
     if(!state.questions.some(x=>x.original===text&&x.status!=='answered'))state.questions.push({id:uid(),text:q,original:text,route:result.route,status:'saved',time:time(),reply:null});
     activity('保存待专业确认的问题；未发送','Saved a professional question; not sent');
   }else activity('引用原文解释；保留对话上下文','Answered with sources; retained conversation context');
 },()=>askPlan(text,true));
}
async function checkUnderstanding(id,answer){
 const item=state.plan.items.find(i=>i.id===id);if(!item||!answer.trim())return;
 await run('check',async()=>{
   const result=await agent('check_understanding',{item,question:checkQuestion(item),answer:answer.trim(),documents:state.documents});
   state.checks[id]={...result,attempts:(state.checks[id]?.attempts||0)+1,answer:answer.trim()};state.draftCheck='';
   activity(result.status==='matched'?'核对了患者对本条的理解':'保留尚未澄清的理解',result.status==='matched'?'Checked understanding of one instruction':'Kept unresolved understanding visible');
   if(state.checks[id].attempts>=2&&result.status!=='matched'&&!state.questions.some(q=>q.itemId===id&&q.status!=='answered'))state.questions.push({id:uid(),itemId:id,text:tr(`我对「${item.title}」的执行方式仍不确定，请帮我确认。`,`I am still unsure how to follow “${item.title}”. Could you clarify?`),route:'source_missing',status:'saved',time:time()});
 },()=>checkUnderstanding(id,answer));
}
function loadDemo(){
 const language=state.lang;
 const candidate=hasVisitContent(state)?nextVisit(state,fresh(),{text:versionedNoteText(),carry:false}):{...fresh(),visit:state.visit,visitHistory:state.visitHistory,lang:state.lang,health:state.health,lastMeta:state.lastMeta};
 Object.assign(candidate,{demo:true,view:'after',plan:demoPlan(language),documents:[{id:'demo-doc',title:tr('虚构门诊记录 · 10月2日','Fictional visit record · Oct 2'),text:demoRecords[language]}],draftPlanText:demoRecords[language]});
 candidate.versions=[{version:1,label:tr('虚构示例计划','Fictional example plan'),time:time(),plan:structuredClone(candidate.plan),documents:structuredClone(candidate.documents)}];
 if(!persistLocal(candidate)){render(false);return;}
 clearPhotoPreviews();state=candidate;retryAction=null;closeModal();activity('加载虚构病例；尚未调用模型','Loaded a fictional case; no model call yet');render();window.scrollTo({top:0,behavior:'smooth'});
}
function openModal(title,body){const modal=$('#modal');modal.className='modal';modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="${tr('关闭','Close')}">${icon('close',18)}</button></div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){$('#modal').close();}
function showSource(id,quote=''){
 const doc=id==='patient'?{title:tr('患者原话','Patient’s original words'),text:state.intake.messages.filter(m=>m.role==='user').map(m=>m.content).join('\n\n')}:findDocument(state,id);
 if(!doc){notify(tr('此来源在旧版本中，请查阅计划版本。','This source belongs to an earlier plan version.'));return;}
 let content=esc(doc.text);const index=quote?doc.text.indexOf(quote):-1;
 if(index>=0)content=esc(doc.text.slice(0,index))+'<mark>'+esc(quote)+'</mark>'+esc(doc.text.slice(index+quote.length));
 openModal(esc(doc.title),`<div class="info-line">${icon('source',15)}<span>${tr('高亮部分是这条信息的原始依据。','The highlighted passage is the original source for this information.')}</span></div><div class="source-text">${content}</div><p class="modal-note">${tr('原文不会因为切换语言或解释深度而改变。','The source does not change when you switch language or explanation depth.')}</p>`);
}
function editFact(index){const f=state.intake.facts[index];openModal(tr('更正你的描述','Correct your description'),`<form data-form="edit-fact" data-index="${index}"><label class="field-label" for="fact-value">${esc(f.label)}</label><textarea id="fact-value" name="value" class="field" rows="3" required maxlength="1000">${esc(f.value)}</textarea><p class="modal-note">${tr('修改会作为你的新原话保留，旧描述仍在对话里。','The correction becomes a new patient statement; the earlier wording remains in the conversation.')}</p><button class="mt-15 button primary" type="submit">${tr('保存更正','Save correction')}</button></form>`);}
function replyDialog(id){const q=state.questions.find(q=>q.id===id);openModal(tr('记录收到的专业回复','Record a professional reply'),`<p>${esc(q.text)}</p><div class="divider"></div><form data-form="reply" data-id="${esc(id)}"><label class="field-label" for="reply-source">${tr('回复来自哪里？','Where did the reply come from?')}</label><input id="reply-source" name="source" class="field" placeholder="${tr('例如：10月3日门诊医生的书面回复','e.g. written reply from the clinician, Oct 3')}" required maxlength="300"><label class="field-label" for="reply-text">${tr('专业人员回复的原文','The professional’s original reply')}</label><textarea id="reply-text" name="reply" class="field" rows="5" required maxlength="15000" placeholder="${tr('粘贴收到的原话，不要由系统补写。','Paste the reply you received; the app does not invent it.')}"></textarea><label class="review-status"><input type="checkbox" name="complete" value="yes">${tr('这是一份完整的新医嘱，需要替换当前计划','This is a complete new plan that replaces the current one')}</label><label class="review-status"><input type="checkbox" name="resolved" value="yes">${tr('这段回复已经解决了我的这个问题','This reply resolves my question')}</label><p class="modal-note">${tr('只记录回复不会更改用药。系统不会联系医院，也不能核验回复者身份。','Recording a reply alone does not change treatment. This prototype does not contact the hospital or verify the author’s identity.')}</p><div class="mt-17 inline-actions"><button class="button primary" type="submit" ${busyAttr()}>${tr('保存回复与来源','Save reply and source')}</button>${state.demo?`<button type="button" class="button ghost" data-action="fill-reply">${tr('填入虚构演示回复','Use a fictional reply')}</button>`:''}</div></form>`);}
async function saveReply(id,reply,source,complete,resolved=false){
 const q=state.questions.find(q=>q.id===id);if(!q)return;
 const doc={id:uid(),title:source,text:reply};
 if(complete){closeModal();await run('plan',async()=>{const result=await agent('extract_plan',{documents:[doc],previousPlan:state.plan});if(!result.items?.length)throw new Error(tr('新医嘱未能形成完整计划，原计划已保留。','The new record could not form a plan. The current plan has been kept.'));Object.assign(state,addPlanVersion(state,result,[doc],{label:tr('专业回复形成新计划','New plan from a professional reply'),time:time()}));state.checks={};state.completed={};recordQuestionReply(q,doc,resolved?'answered':'replied');activity('依据完整新医嘱更新计划；保留旧版本','Updated from a complete new plan; retained the previous version');state.view='after';},()=>saveReply(id,reply,source,complete,resolved));}
 else{const previousVersion=state.plan?.version;state.documents.push(doc);recordQuestionReply(q,doc,resolved?'answered':'replied');if(state.plan)Object.assign(state,addPlanVersion(state,state.plan,state.documents,{label:tr('补充专业回复；原安排不变','Professional reply added; instructions unchanged'),time:time(),reviewed:state.plan?.reviewed||false}));for(const reminder of state.reminders)if(state.plan&&reminder.version===previousVersion)reminder.version=state.plan.version;activity('记录专业回复与来源；未自动改变治疗','Recorded a professional reply; treatment not automatically changed');closeModal();render();notify(tr('回复已记录，之后的追问可以引用它。','Reply saved. Future questions can refer to it.'));}
}
async function importFile(file){
 if(!file)return;if(file.size>8*1024*1024){notify(tr('文件请小于 8 MB。','Choose a file under 8 MB.'));return;}
 let extracted;
 await run('upload',async()=>{const body=new FormData();body.append('file',file);body.append('language',state.lang);const res=await fetch('/api/extract-document',{method:'POST',body,signal:AbortSignal.timeout(65000)});const data=await res.json();if(!res.ok||!data.ok)throw new Error(data.error?.message||tr('无法读取文件。请尝试粘贴文字。','Could not read this file. Try pasting the text.'));extracted=data.document;activity('读取用户选择的资料文件','Read the selected document');if(uploadContext==='plan'){state.draftPlanText=(state.draftPlanText?state.draftPlanText+'\n\n':'')+extracted.text;state.ocrPending=state.ocrPending||Boolean(extracted.requiresReview);state.ocrReviewed=false;if(extracted.extraction==='ocr')state.photoPreviews.push({title:extracted.title,url:URL.createObjectURL(file)});state.view='doctor';}},()=>importFile(file));
 if(extracted&&uploadContext==='intake'){if(extracted.requiresReview){state.recordDraft=extracted;render();reviewRecordDialog();}else{state.intake.records.push(extracted);await sendIntake(tr('我提供了一份已有资料：','I supplied an existing record: ')+extracted.title,false,false,true);}}
}
function questionStatusText(q){return {saved:tr('已保存，未发送','Saved, not sent'),sent:tr('患者标记已发出','Patient marked sent'),replied:tr('已记录回复，仍待确认','Reply recorded, still open'),answered:tr('患者标记已解决','Patient marked resolved')}[q.status]||q.status;}
function briefText(){
 const pending=state.questions.filter(q=>q.status!=='answered'),carried=state.questions.filter(q=>q.origin);
 return [tr('诊前摘要','Pre-visit brief')+' · '+visitLabel(state.visit.number),
  state.carryover?tr('历史交接摘要（请核对哪些情况仍然适用）','Historical handoff (please check what still applies)')+' · '+visitLabel(state.carryover.visitNumber)+'\n'+state.carryover.summary:'',
  carried.length?tr('带入问题的当前状态 / 已跟进的问题','Current status / updates to carried questions')+'\n'+carried.map(q=>`${q.text}\n${questionStatusText(q)} · ${tr('最初来自','Originally from')} ${visitLabel(q.origin.visitNumber)}${q.reply?'\n'+tr('已记录回复：','Recorded reply: ')+q.reply+'\n'+tr('来源：','Source: ')+(q.replySource||'')+' · '+tr('由患者录入，身份未核验','Patient entered; identity unverified'):''}`).join('\n\n'):'',
  pending.length?tr('本次待询问的问题','Questions for this visit')+'\n'+pending.map(q=>q.text).join('\n'):'',
  tr('本次患者描述','Current patient account'),state.intake.reviewed?tr('患者已核对','Patient reviewed'):tr('患者未核对','Not patient reviewed'),
  ...state.intake.facts.map(f=>`${f.label}: ${f.value}\n  ${tr('原话','Original words')}: ${f.quote}`),
  state.intake.unknowns.length?tr('待澄清','Unresolved')+': '+state.intake.unknowns.join('; '):''].filter(Boolean).join('\n\n');
}

function noteText(){
 const parts=[tr('AfterDoc — 给下一次就诊的小纸条','AfterDoc — Note for the next visit'),visitLabel(state.visit.number),new Date().toLocaleString(),state.demo?tr('虚构演示病例','Fictional demonstration case'):'',briefText(),tr('本次书面计划','Documented care plan')];
 for(const item of state.plan?.items||[])parts.push(`${item.title}: ${[item.dose,item.frequency,item.duration,item.timing].filter(Boolean).join(' / ')}\n${tr('原文','Source')}: ${item.sourceQuote}\n${tr('患者标记','Patient report')}: ${state.completed[item.id]?tr('已记下安排','Arrangement noted'):tr('未标记','Not marked')} · ${tr('理解核对','Understanding check')}: ${checkName(state.checks[item.id]?.status)}`);
 const history=planVersions(state).filter(v=>v.version!==state.plan?.version);
 if(history.length){
   parts.push(tr('历史计划（仅供回顾，不是当前执行安排）','Previous plans (for reference, not current instructions)'));
   for(const v of history){
     parts.push(`V${v.version} · ${v.label} · ${v.time}`);
     for(const item of v.plan?.items||[])parts.push(`${item.title}\n${tr('原文','Source')}: ${item.sourceQuote}\n${checkName(v.checks?.[item.id]?.status)} · ${v.completed?.[item.id]?tr('患者已记下安排','Patient noted the arrangement'):tr('患者未标记安排','No patient arrangement marker')}`);
   }
 }
 parts.push(tr('患者设置的提醒（不是用药完成记录）','Patient-set reminders (not a medication adherence record)'));
 for(const r of state.reminders)parts.push(`${r.title} · ${r.start} · ${r.timeZone} · ${r.count} ${tr('天','days')} · V${r.version} · ${r.synced?tr('已写入Google','Saved to Google'):tr('未写入Google','Not saved to Google')}`);
 parts.push(tr('期间提出的问题与变化','Questions and changes'));parts.push(...state.postMessages.filter(m=>m.role==='user').map(m=>m.content));
 parts.push(tr('需要专业人员确认 / 已记录回复','Professional questions / recorded replies'));
 for(const q of state.questions)parts.push(`${q.text}\n${tr('状态','Status')}: ${{saved:tr('已保存，未发送','Saved, not sent'),sent:tr('患者标记已发出','Patient marked sent'),replied:tr('已记录回复，仍待确认','Reply recorded, still open'),answered:tr('患者标记已解决','Patient marked resolved')}[q.status]||q.status}\n${q.reply?`${q.reply}\n${tr('来源','Source')}: ${q.replySource} (${tr('用户录入，未核验身份','User supplied; identity not verified')})`:tr('未获得回复。已保存不代表已发送。','No reply recorded. Saved does not mean sent.')}`);
 for(const [label,draft] of [[tr('尚未发送的诊前草稿','Unsubmitted pre-visit draft'),state.draftIntake],[tr('尚未发送的问题草稿','Unsubmitted question draft'),state.draftPost],[tr('待整理的资料文字','Record text awaiting extraction'),state.documents.some(doc=>doc.text.trim()===state.draftPlanText.trim())?'':state.draftPlanText],[tr('尚未提交的理解核对','Unsubmitted understanding check'),state.draftCheck]])if(draft)parts.push(label+'\n'+draft);
 if(state.recordDraft)parts.push(tr('待核对的识别文字（尚未作为资料提交）','OCR text awaiting review (not yet submitted as a record)')+'\n'+state.recordDraft.text);
 parts.push(tr('沟通辅助原型；保留原文和未确认信息，不作医疗决策。','Communication prototype. Sources and uncertainty are retained; this tool does not make clinical decisions.'));
 return parts.filter(Boolean).join('\n\n');
}
async function copy(text){try{await navigator.clipboard.writeText(text);notify(tr('已复制。','Copied.'));}catch{openModal(tr('复制以下文字','Copy the text below'),`<textarea class="field" rows="12" readonly>${esc(text)}</textarea>`);}}
async function exportNote(){const saved=saveCurrentNote(false);await offerDownload({type:'note',text:saved?state.noteVersions.at(-1).text:noteText()});}
function confirmReset(demo=false){
 if(state.busy){notify(tr('当前步骤完成后，再开始下一次就诊。','Wait for this step before starting the next visit.'));return;}
 if(!demo&&!hasVisitContent(state)){notify(tr('本次还没有新增记录，先继续填写这次就诊。','This visit has no new information yet. Continue this visit first.'));return;}
 openModal(demo?tr('打开虚构演示病例？','Open the fictional case?'):tr('准备下一次就诊','Prepare the next visit'),`<p>${demo?tr('当前就诊会保存为历史记录；虚构病例单独开启，不带入真实问题。','Your current visit will be archived; the fictional case opens separately without carrying real questions.'):tr('先保存本次小纸条，再带着上次摘要和未解决的问题开始下一次诊前准备。已解决的问题保留在历史中。','Save this note, then begin a fresh pre-visit account with the previous summary and unresolved questions. Resolved questions remain in history.')}</p><p class="modal-note">${tr('新的就诊从空白医嘱和理解核对开始。旧用药提醒保留在历史中；已经加入外部日历的活动不会被修改或删除。','The new visit starts with a fresh plan and understanding checks. Older reminder settings stay in history; events already added to an external calendar are not changed or removed.')}</p><div class="inline-actions mt-20"><button class="button primary" data-action="${demo?'confirm-demo':'confirm-next-visit'}">${demo?tr('保存并打开演示','Save & open demo'):tr('保存并开始下一次','Save & start next visit')}</button><button class="button secondary" data-action="close-modal">${tr('继续本次就诊','Stay in this visit')}</button></div>`);
}
function clearPhotoPreviews(){for(const photo of state.photoPreviews)URL.revokeObjectURL(photo.url);state.photoPreviews=[];}

function visitLabel(number){return tr(`第 ${number} 次就诊`,`Visit ${number}`);}
function dateLabel(value){return new Date(value).toLocaleString(state.lang==='en'?'en-US':'zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function persistLocal(candidate=state){const result=localStore.save(candidate);storageError=result.error||null;return result.ok;}
function updateStorageFeedback(){const el=$('#storage-feedback');if(el)el.innerHTML=storageBanner();}
function storageBanner(){
 if(!storageError)return `<div class="local-status">${icon('check',12)}${tr('已保存在此浏览器','Saved in this browser')}<span>· ${tr('草稿自动保存，正式版本由你保存','Draft autosaves; save note versions when ready')}</span></div>`;
 const message=storageError.code==='conflict'?tr('另一个页面更新了就诊记录。本页已停止保存，避免覆盖；可先导出本页，再加载最新记录。','Another page updated these visits. Saving here is paused to avoid overwriting it. Export this page before loading the latest records.'):storageError.code==='corrupt'?tr('无法读取本机历史记录，原副本未被覆盖。本页更改尚未保存；可下载原副本，再决定是否清除。','Stored records could not be read; the original copy is untouched. Changes here are not saved. Download that copy before deciding whether to clear it.'):tr('本机保存失败，最近更改尚未保存。可能是浏览器限制或空间不足；请先导出备份。','Local saving failed. Recent changes are not saved. Storage may be restricted or full; export a backup first.');
 return `<div class="banner storage-warning" role="alert">${icon('info',17)}<div class="text"><strong>${tr('尚未保存到本机','Not saved locally')}</strong>${message}<div class="inline-actions mt-10"><button class="button secondary small" data-action="export-note">${tr('导出本页小纸条','Export this note')}</button><button class="button secondary small" data-action="export-storage">${tr('下载已存历史副本','Download stored backup')}</button>${storageError.code==='conflict'?`<button class="button secondary small" data-action="reload-local">${tr('加载最新记录','Load latest records')}</button>`:storageError.code==='corrupt'?`<button class="button ghost small" data-action="clear-local">${tr('清除本机记录…','Clear stored records…')}</button>`:`<button class="button secondary small" data-action="retry-storage">${tr('重试保存','Retry saving')}</button>`}</div></div></div>`;
}
function carryoverPanel(compact=false){
 if(!state.carryover)return '';
 return `<section class="carryover-card ${compact?'compact':''}"><div class="carryover-head"><span class="icon-box">${icon('history',18)}</span><div><h3>${tr('从上一次，接着说','Pick up from the previous visit')}</h3><p>${visitLabel(state.carryover.visitNumber)} · ${esc(dateLabel(state.carryover.endedAt))}${state.demo?' · '+tr('虚构演示','Fictional case'):''}</p></div><button class="button secondary small" data-action="archived-visit" data-visit="${esc(state.carryover.visitId)}">${tr('回看小纸条','Previous note')}</button></div><p class="field-help">${tr('以下是历史记录，请告诉我们哪些情况有变化。本次医嘱和理解核对会重新记录。','This is a historical handoff. Tell us what changed. The current visit gets its own plan and understanding checks.')}</p><details><summary>${tr('展开上次摘要','Expand previous summary')}</summary><div class="carryover-summary">${esc(state.carryover.summary||tr('上次只有草稿，可回看完整小纸条。','The previous visit contained drafts; open the full note.'))}</div></details>${!compact?`<div class="inline-actions mt-15"><button class="button secondary small" data-action="show-brief">${icon('user',14)}${tr('展示给医生','Show the clinician')}</button><span class="field-help">${state.questions.filter(q=>q.status!=='answered').length} ${tr('个问题仍待确认','questions still open')}</span></div>`:''}</section>`;
}
function noteVersionBar(){
 const latest=state.noteVersions.at(-1),changed=noteHasChanges(state);
 return `<section class="visit-cycle-bar"><div><span class="eyebrow">${visitLabel(state.visit.number)}</span><h2>${latest?tr(`小纸条 v${latest.revision}${changed?' 后有新变化':''}`,`Note v${latest.revision}${changed?' · new changes':''}`):tr('小纸条草稿','Living note draft')}</h2><p>${latest?tr(`上次存版：${dateLabel(latest.savedAt)}`,`Last version saved: ${dateLabel(latest.savedAt)}`):tr('保存一个版本，留下这次沟通的原样。','Save a version to keep this point in the conversation.')}</p></div><div class="inline-actions"><button class="button secondary" data-action="save-note" ${busyAttr()}>${icon('check',15)}${tr('保存小纸条版本','Save note version')}</button><button class="button primary" data-action="reset" ${busyAttr()}>${tr('准备下一次就诊','Prepare next visit')}${icon('arrow',15)}</button></div></section>`;
}
function revisionButton(visit,revision){return `<button class="plan-version version-button" data-action="note-revision" data-visit="${esc(visit.id)}" data-revision="${esc(revision.id)}"><span>${tr('小纸条','Note')} v${revision.revision}</span><span class="muted tiny">${esc(dateLabel(revision.savedAt))} ↗</span></button>`;}
function noteHistoryPanel(){
 return `<section class="care-note revision-history"><div class="note-title"><h2>${icon('history',17)}${tr('小纸条版本','Note versions')}</h2></div><h3>${visitLabel(state.visit.number)} · ${tr('当前就诊','Current visit')}</h3>${state.noteVersions.length?[...state.noteVersions].reverse().map(v=>revisionButton(state.visit,v)).join(''):`<p class="note-empty">${tr('草稿在本机自动保存。点击“保存小纸条版本”建立可回看的版本。','The draft autosaves locally. Choose “Save note version” to create a reviewable version.')}</p>`}${state.visitHistory.length?`<div class="divider"></div><h3>${tr('之前的就诊','Previous visits')}</h3>${[...state.visitHistory].reverse().map(h=>`<details class="visit-history-group"><summary>${visitLabel(h.visit.number)}${h.demo?' · '+tr('虚构演示','Fictional'):''}<span>${h.noteVersions.length} ${tr('个版本','versions')}</span></summary>${[...h.noteVersions].reverse().map(v=>revisionButton(h.visit,v)).join('')}</details>`).join('')}`:''}<p class="field-help">${tr('保存的版本只供回看，不会因之后的修改而变化。','Saved versions stay unchanged as your current note develops.')}</p></section>`;
}
function versionedNoteText(){return `${visitLabel(state.visit.number)} · ${tr('小纸条版本','Note version')} v${state.noteVersions.length+(noteHasChanges(state)?1:0)}\n\n${noteText()}`;}
function saveCurrentNote(showToast=true){
 if(state.busy){notify(tr('当前步骤完成后再保存版本。','Wait for this step before saving a version.'));return false;}
 if(!hasVisitContent(state)){if(showToast)notify(tr('先记录本次就诊的内容。','Add something to this visit first.'));return false;}
 const changed=noteHasChanges(state),candidate={...state,...saveNoteVersion(state,{text:versionedNoteText()})};
 if(!persistLocal(candidate)){render(false);return false;}
 state=candidate;render(false);if(showToast)notify(changed?tr(`已保存小纸条 v${state.noteVersions.length}。`,`Saved note v${state.noteVersions.length}.`):tr('内容没有变化，保留现有版本。','No content changed; the existing version is kept.'));return true;
}
function lookupRevision(visitId,revisionId){const list=visitId===state.visit.id?state.noteVersions:state.visitHistory.find(h=>h.visit.id===visitId)?.noteVersions;return revisionId?list?.find(v=>v.id===revisionId):list?.at(-1);}
function showNoteRevision(visitId,revisionId){
 const revision=lookupRevision(visitId,revisionId);if(!revision)return;
 const snapshot=revision.snapshot,sources=[...snapshot.documents,...snapshot.intake.records,...snapshot.versions.flatMap(v=>v.documents||[]),...snapshot.questions.flatMap(questionDocuments)];
 const unique=sources.filter((doc,index)=>sources.findIndex(d=>d.id===doc.id&&d.text===doc.text)===index);
 const words=snapshot.intake.messages.filter(m=>m.role==='user').map(m=>m.content).join('\n\n');
 openModal(`${visitLabel(snapshot.visit.number)} · ${tr('小纸条','Note')} v${revision.revision}`,`<p class="info-line">${icon('history',15)}${tr('已保存版本 · 只读 · 不会设为当前医嘱','Saved version · Read only · Does not activate an earlier plan')}</p><p class="field-help">${esc(dateLabel(revision.savedAt))}</p><div class="source-text saved-note-text">${esc(revision.text)}</div><details class="saved-sources"><summary>${tr('本版本保留的完整来源','Full sources retained in this version')} (${unique.length})</summary>${words?`<h3>${tr('患者当时的原话','The patient’s words at the time')}</h3><div class="source-text">${esc(words)}</div>`:''}${unique.map(doc=>`<h3>${esc(doc.title)}</h3><div class="source-text">${esc(doc.text)}</div>`).join('')||(!words?`<p>${tr('本版本没有原始资料。','No source records in this version.')}</p>`:'')}</details><button class="button primary mt-18" data-action="export-revision" data-visit="${esc(visitId)}" data-revision="${esc(revision.id)}">${icon('down',15)}${tr('导出这个版本','Export this version')}</button>`);
}
function startNextVisit(){
 if(state.busy||!hasVisitContent(state))return;
 const candidate=nextVisit(state,fresh(),{text:versionedNoteText()});
 if(!persistLocal(candidate)){closeModal();render(false);return;}
 clearPhotoPreviews();state=candidate;retryAction=null;closeModal();render(false);window.scrollTo({top:0,behavior:'smooth'});notify(tr('上次已归档，可以开始这次诊前准备了。','Previous visit archived. Your next pre-visit preparation is ready.'));
}
function recordRecoveryPanel(){return state.recordDraft?`<div class="banner">${icon('camera',18)}<div class="text"><strong>${tr('还有一份诊前照片文字待核对','A pre-visit photo transcript still needs review')}</strong>${tr('文字已保存，尚未作为资料提交。请对照原图继续检查。','The text is saved but has not been submitted as a record. Continue checking against your original photo.')}</div><button class="button secondary small" data-action="resume-record">${tr('继续核对','Resume review')}</button></div>`:'';}
function reviewRecordDialog(){
 if(!state.recordDraft)return;
 openModal(tr('先核对识别文字','Check the recognized text'),`<form data-form="review-record"><p class="field-help">${tr('请对照手机或原文件中的照片核对。原始照片不会随刷新保留，文字草稿会保留。','Check this against the photo on your phone or in the original file. The text draft survives refresh; the original photo does not.')}</p><label for="ocr-intake" class="field-label">${tr('识别出的原文','Recognized source text')}</label><textarea id="ocr-intake" name="text" class="field" rows="12" required maxlength="30000">${esc(state.recordDraft.text)}</textarea><label class="review-status"><input name="reviewed" type="checkbox" required>${tr('我已对照原图核对这些文字','I checked this text against the original photo')}</label><div class="inline-actions mt-15"><button class="button primary" type="submit">${tr('已核对，继续整理','Checked — continue')}</button><button type="button" class="button ghost" data-action="discard-record">${tr('放弃这份未提交的文字','Discard this unsubmitted draft')}</button></div></form>`);
}
function confirmClearLocal(){openModal(tr('清除此浏览器的所有就诊记录？','Clear all visits from this browser?'),`<p>${tr('这会删除本浏览器保存的所有就诊、小纸条版本与草稿，无法在这里撤销。已导出的文件和日历活动保留。','This removes all locally saved visits, note versions and drafts. This cannot be undone here. Exported files and calendar events remain.')}</p><div class="inline-actions mt-18"><button class="button secondary" data-action="export-storage">${tr('先下载历史副本','Download backup first')}</button><button class="button primary" data-action="confirm-clear-local" ${busyAttr()}>${tr('清除所有本机记录','Clear all local records')}</button></div>`);}
function clearLocal(){if(state.busy)return;const result=localStore.clear();if(!result.ok){storageError=result.error;closeModal();render(false);return;}clearPhotoPreviews();const {lang,health}=state;state={...fresh(),lang,health};retryAction=null;closeModal();render();notify(tr('此浏览器的就诊记录已清除。','Visits in this browser were cleared.'));}
function confirmReloadLocal(){openModal(tr('加载另一个页面保存的最新记录？','Load the latest records saved by the other page?'),`<p>${tr('本页未保存的修改会被替换。你可以先导出本页小纸条，再加载最新记录。','Unsaved changes on this page will be replaced. Export this note before loading the latest saved records.')}</p><div class="inline-actions mt-18"><button class="button secondary" data-action="export-note">${tr('先导出本页','Export this page first')}</button><button class="button primary" data-action="confirm-reload-local" ${busyAttr()}>${tr('替换本页并加载最新记录','Replace this page & load latest')}</button></div>`);}
function reloadLocal(){if(state.busy)return;const loaded=localStore.load(fresh());if(loaded.error){storageError=loaded.error;closeModal();render(false);return;}clearPhotoPreviews();const health=state.health;state={...loaded.state,health};storageError=null;retryAction=null;closeModal();render();}
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY||event.key===null){storageError={code:'conflict'};updateStorageFeedback();}});

document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-action]');if(!button||button.disabled)return;
 const action=button.dataset.action;if(button.tagName==='A')e.preventDefault();
 if(action==='view'){state.view=button.dataset.view;state.error=null;render();window.scrollTo({top:0,behavior:'smooth'});}
 else if(action==='language'){state.lang=state.lang==='zh'?'en':'zh';render();notify(tr('界面已切换；原文和已有对话保留原语言。','Interface switched; source records and existing messages keep their language.'));}
 else if(action==='starter')await sendIntake(starterStory[state.lang]);
 else if(action==='clarify-option')await sendIntake(button.dataset.value);
 else if(action==='finish-intake')await sendIntake('',true);
 else if(action==='review-intake'){state.intake.reviewed=true;activity('患者核对了自己的描述','Patient reviewed the descriptions');render();notify(tr('已记录你的确认，医生仍需核对医学表述。','Your review is recorded. Clinical wording still needs clinician verification.'));}
 else if(action==='edit-fact')editFact(Number(button.dataset.index));
 else if(action==='reminder')reminderDialog(button.dataset.id);
 else if(action==='calendar-manager'||action==='refresh-calendar')await calendarManager();
 else if(action==='connect-calendar')await connectCalendar();
 else if(action==='disconnect-calendar'){await calendarRequest('/api/calendar/disconnect',{});await calendarManager();}
 else if(action==='export-calendar')exportCalendar();
 else if(action==='sync-calendar')await syncCalendar();
 else if(action==='remove-reminder'){state.reminders=state.reminders.filter(r=>r.id!==button.dataset.id);render();await calendarManager(false);}
 else if(action==='show-brief')showBrief();
 else if(action==='continue-records'){closeModal();state.view='doctor';render();}
 else if(action==='camera'){uploadContext='plan';$('#photo-file').value='';$('#photo-file').click();}
 else if(action==='source')showSource(button.dataset.source,button.dataset.quote);
 else if(action==='version'){const v=planVersions(state).find(v=>v.version===Number(button.dataset.version));if(v)openModal(tr('计划版本','Plan version')+' V'+v.version,`<p class="muted">${esc(v.label)} · ${esc(v.time)}</p>${v.plan?.items.map(i=>`<div class="divider"></div><h3>${esc(i.title)}</h3><p>${esc(i.sourceQuote||i.details)}</p><p class="field-help">${esc(checkName(v.checks?.[i.id]?.status))} · ${v.completed?.[i.id]?tr('患者已记下安排','Patient noted the arrangement'):tr('患者未标记安排','No patient arrangement marker')}</p><div class="mt-10">${sourceButton(i.sourceId,i.sourceQuote)}</div>`).join('')||''}<div class="divider"></div><p class="field-help">${tr('历史版本用于回顾；当前计划版本是','Historical versions are for reference. The current version is')} V${state.plan?.version||1}.</p>`);}
 else if(action==='preference'){state.preference=button.dataset.value;activity(state.preference==='brief'?'切换为简短指引；关键事项保留':'切换为详细解释；关键事项保留',state.preference==='brief'?'Switched to brief guidance; essentials retained':'Switched to detailed explanations; essentials retained');render();}
 else if(action==='toggle-item'){state.completed[button.dataset.id]=!state.completed[button.dataset.id];render();}
 else if(action==='open-check'){state.checkOpen=button.dataset.id;state.draftCheck='';render();}
 else if(action==='close-check'){state.checkOpen=null;render();}
 else if(action==='skip-check'){const id=button.dataset.id;state.checks[id]={...state.checks[id],status:'skipped'};state.checkOpen=null;activity('患者跳过核对；不标记为理解正确','Patient skipped the check; not marked as understood');render();}
 else if(action==='ask-suggestion')await askPlan(button.dataset.question);
 else if(action==='confirm-plan'){state.plan.reviewed=true;activity('用户核对了提取结果与原文','User reviewed the extraction against the source');render();}
 else if(action==='fill-record'){state.draftPlanText=demoRecords[state.lang];state.demo=true;state.ocrPending=false;state.ocrReviewed=false;state.ocrPhotoMissing=false;clearPhotoPreviews();render();}
 else if(action==='upload'){uploadContext=button.dataset.context;$('#document-file').value='';$('#document-file').click();}
 else if(action==='record-reply')replyDialog(button.dataset.id);
 else if(action==='mark-sent'){const q=state.questions.find(q=>q.id===button.dataset.id);if(q){q.status='sent';activity('患者自行标记问题已发出','Patient marked the question as sent themselves');render();notify(tr('已标记。AfterDoc 没有代你发送任何消息。','Marked. AfterDoc has not sent any message for you.'));}}
 else if(action==='fill-reply'){$('#reply-source').value=tr('虚构演示：门诊医生书面回复','Fictional demo: written clinician reply');$('#reply-text').value=tr('这是虚构演示回复：请按原记录继续执行。本次回复未提供漏服处理细则，漏服问题仍需电话联系开方医生确认。','Fictional demo reply: continue following the original record. This reply does not provide missed-dose instructions; that question still needs clarification from the prescribing clinician.');}
 else if(action==='copy-brief')await copy(briefText());
 else if(action==='copy-note')await copy(noteText());
 else if(action==='export-note')exportNote();
 else if(action==='demo')confirmReset(true);
 else if(action==='reset')confirmReset();
 else if(action==='confirm-demo'){closeModal();loadDemo();}
 else if(action==='confirm-next-visit')startNextVisit();
 else if(action==='save-note')saveCurrentNote();
 else if(action==='note-revision')showNoteRevision(button.dataset.visit,button.dataset.revision);
 else if(action==='archived-visit')showNoteRevision(button.dataset.visit);
 else if(action==='export-revision'){const version=lookupRevision(button.dataset.visit,button.dataset.revision);if(version)await offerDownload({type:'note',text:version.text});}
 else if(action==='resume-record')reviewRecordDialog();
 else if(action==='discard-record'){state.recordDraft=null;closeModal();render();}
 else if(action==='clear-local')confirmClearLocal();
 else if(action==='confirm-clear-local')clearLocal();
 else if(action==='reload-local')confirmReloadLocal();
 else if(action==='confirm-reload-local')reloadLocal();
 else if(action==='retry-storage'){persistLocal();render(false);}
 else if(action==='export-storage'){const raw=localStore.raw();if(raw===null){notify(tr('本机没有可读取的历史副本。','No stored backup is readable.'));return;}await offerDownload({type:'backup',text:raw});}
 else if(action==='close-modal')closeModal();
 else if(action==='retry'&&retryAction){const retry=retryAction;retryAction=null;await retry();}
 else if(action==='dismiss-error'){state.error=null;retryAction=null;render();}
 else if(action==='activity')openModal(tr('本次会话的活动记录','Session activity'),state.activities.map(a=>`<div class="plan-version"><span>${esc(state.lang==='en'?a.en:a.zh)}</span><time class="tiny muted">${esc(a.time)}</time></div>`).join('')||`<p>${tr('还没有活动。','No activity yet.')}</p>`);
 else if(action==='about')openModal(tr('关于 AfterDoc 原型','About this AfterDoc prototype'),`<p>${tr('这个可运行原型演示诊前澄清、医嘱交接和个性化诊后支持。自由输入由 DeepSeek 处理；虚构演示资料会明确标注。','This working prototype demonstrates pre-visit clarification, the clinician handoff and adaptive post-visit support. DeepSeek handles free-text input; fictional demo records are labeled.')}</p><div class="divider"></div><p>${tr('就诊记录、小纸条版本和草稿保存在此浏览器，刷新后可以继续；共享设备上的其他使用者也可能看到这些内容。原始照片仅在当前页面保留。发送的问题、相关资料与上次就诊的有限摘要会交给 DeepSeek API；原型不连接医院、不代发消息、不做医疗决策。','Visit records, note versions and drafts stay in this browser across refreshes; other people using a shared device may see them. Original photos remain in this page only. Submitted questions, relevant records and a bounded previous-visit summary are sent to the DeepSeek API. The prototype does not connect to a hospital, send messages to clinicians or make medical decisions.')}</p><button class="button secondary mt-18" data-action="clear-local">${tr('清除此浏览器的所有就诊记录','Clear all visits from this browser')}</button>`);
});
document.addEventListener('submit',async e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(state.busy)return;
 const data=new FormData(form),type=form.dataset.form;
 if(type==='intake')await sendIntake(String(data.get('message')||''));
 else if(type==='post')await askPlan(String(data.get('message')||''));
 else if(type==='timeline'){const onset=String(data.get('onset')||'').trim(),duration=String(data.get('duration')||'').trim();if(onset||duration)await sendIntake([onset?tr('开始时间：','Started: ')+onset:'',duration?tr('每次持续：','Each episode lasts: ')+duration:''].filter(Boolean).join('；'));}
 else if(type==='reminder')saveReminder(form.dataset.id,data);
 else if(type==='review-record'){const doc={...state.recordDraft,text:String(data.get('text')||'').trim()};state.intake.records.push(doc);state.recordDraft=null;closeModal();await sendIntake(tr('我提供了一份已有资料：','I supplied an existing record: ')+doc.title,false,false,true);}
 else if(type==='plan')await extractPlan(state.draftPlanText);
 else if(type==='check')await checkUnderstanding(form.dataset.id,String(data.get('answer')||''));
 else if(type==='edit-fact'){const i=Number(form.dataset.index),value=String(data.get('value')||'').trim();if(value){const quote=tr('更正：','Correction: ')+state.intake.facts[i].label+' '+value;state.intake.messages.push({role:'user',content:quote});state.intake.facts[i]={...state.intake.facts[i],value,quote,sourceId:'patient',certainty:'corrected'};markPatientCorrection(state);activity('保留患者更正及原始表述','Kept the patient correction and earlier wording');closeModal();render();}}
 else if(type==='reply')await saveReply(form.dataset.id,String(data.get('reply')||'').trim(),String(data.get('source')||'').trim(),data.get('complete')==='yes',data.get('resolved')==='yes');
});
document.addEventListener('input',e=>{if(e.target.dataset.draft){state[e.target.dataset.draft]=e.target.value;if(e.target.dataset.draft==='draftPlanText'&&state.ocrPending){state.ocrReviewed=false;const check=$('#ocr-reviewed');if(check)check.checked=false;}persistLocal();updateStorageFeedback();}if(e.target.id==='ocr-intake'&&state.recordDraft){state.recordDraft.text=e.target.value;persistLocal();updateStorageFeedback();}});
document.addEventListener('change',e=>{if(e.target.id==='ocr-reviewed'){state.ocrReviewed=e.target.checked;persistLocal();updateStorageFeedback();}if(e.target.id==='document-file'||e.target.id==='photo-file')importFile(e.target.files[0]);});
document.addEventListener('keydown',e=>{if((e.target.id==='intake-input'||e.target.id==='post-input')&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!state.busy)e.target.form.requestSubmit();}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
fetch('/api/health').then(r=>r.json()).then(health=>{state.health=health;render();}).catch(()=>{state.error=tr('本地服务未连接，请从启动脚本打开原型。','Local server unavailable. Open the prototype using the start script.');render();});
